public class Main {
    public static void main(String[] args) {
        int point = 100;
        System.out.println("ポイント: " + point);

        point += 50;
        System.out.println("ポイント: " + point);

        point -= 30;
        System.out.println("ポイント: " + point);

        point *= 2;
        System.out.println("ポイント: " + point);
    }
}

