lessons.solution:
public class Main {
    public static void main(String[] args) {
        int x = 7;
        int y = 3;

        System.out.println(x + " + " + y + " = " + (x + y));
        System.out.println(x + "と" + y + "をつなぐと" + x + y);
        System.out.println("残りは " + (x - y) + " です");
    }
}
